//! What setting or clearing the System does to the other attributes of a
//! SpecFrame, TimeFrame or FluxFrame, checked against the C library.
//!
//! `system_change_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/system_change_probe.c`. When the System changes,
//! the Label, Symbol and Title, whose defaults depend on it, are cleared,
//! and the Unit last used with the new System is restored, or cleared
//! (specframe.c, timeframe.c, fluxframe.c `SetSystem` and `ClearSystem`).

#[path = "system_change_oracle/cases.rs"]
mod cases;

use ast_core::frames::{
    DynFrame, FluxFrame, FluxSystem, Frame, SpecFrame, SpecSystem, TimeFrame, TimeSystem,
};

/// The probe's `mine` settings.
fn mine(f: &mut dyn Frame) {
    f.set_label(1, "Mine").unwrap();
    f.set_symbol(1, "M").unwrap();
    f.set_title("Mine").unwrap();
}

fn spec(system: SpecSystem, unit: &str) -> SpecFrame {
    let mut f = SpecFrame::new(system);
    f.set_unit(1, unit).unwrap();
    mine(&mut f);
    f
}

fn time(system: TimeSystem) -> TimeFrame {
    let mut f = TimeFrame::new(TimeSystem::Mjd);
    f.set_system(system);
    mine(&mut f);
    f
}

fn run(name: &str) -> DynFrame {
    match name {
        "spec_set_vrad" | "spec_set_back_to_freq" => {
            let mut f = spec(SpecSystem::Freq, "MHz");
            f.set_system(SpecSystem::Vradio);
            if name == "spec_set_back_to_freq" {
                f.set_system(SpecSystem::Freq);
            }
            Box::new(f)
        }
        "spec_clear" => {
            let mut f = spec(SpecSystem::Freq, "MHz");
            f.clear_system();
            Box::new(f)
        }
        "spec_clear_unchanged" => {
            let mut f = spec(SpecSystem::Wavelen, "nm");
            f.clear_system();
            Box::new(f)
        }
        "time_set_jd" => {
            let mut f = time(TimeSystem::Mjd);
            f.set_system(TimeSystem::Jd);
            Box::new(f)
        }
        "time_clear" | "time_clear_bepoch" => {
            let system = if name == "time_clear" {
                TimeSystem::Jd
            } else {
                TimeSystem::Bepoch
            };
            let mut f = time(system);
            f.clear_system();
            Box::new(f)
        }
        "flux_set_sfcbr" => {
            let mut f = FluxFrame::unset_system();
            f.set_system(FluxSystem::FluxDen);
            f.set_unit(1, "Jy").unwrap();
            mine(&mut f);
            f.set_system(FluxSystem::SBright);
            Box::new(f)
        }
        other => panic!("no Rust set-up for case {other}"),
    }
}

#[test]
fn system_changes_match_the_c_library() {
    let mut failures = Vec::new();
    for &(name, system, label, symbol, title, unit) in cases::CASES {
        let f = run(name);
        let got = (
            f.system_string().unwrap_or("").to_string(),
            f.label(1).unwrap(),
            f.symbol(1).unwrap(),
            f.title(),
            f.unit(1).unwrap(),
        );
        let want = (
            system.to_string(),
            label.to_string(),
            symbol.to_string(),
            title.to_string(),
            unit.to_string(),
        );
        if got != want {
            failures.push(format!("{name}: got {got:?}, C gives {want:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
